def decode_git_bytes(raw) -> str:
    """把 Git 输出（str 或 bytes）归一化成可 JSON/HTTP 序列化的干净文本。

    历史失败：Git 的 diff / show 输出按路径、内容逐字节透传，仓库里一旦存在非 UTF-8 字节
    （GBK/Latin-1 编码的老文件、带 BOM 的源码、二进制近似文件），后续 json.dumps 与 HTTP
    响应编码就会抛 UnicodeEncodeError/UnicodeDecodeError，整次评审中断。

    这里只做「展示层」归一化：先按 UTF-8 严格解码（保留全部合法 Unicode，包括中文、emoji、
    组合字符），失败才按 UTF-8 容错解码（非法字节替换为 U+FFFD，不丢行、不多行）；再剔除
    JSON 不允许的孤立代理项与 NUL。原始 blob（blob_oids / git show 二进制通路）与严格解码的
    revision 源码路径（decode_git_diff_path / rev 源码读取）不经过本函数，字节完全保留。
    """
    if raw is None:
        return ""
    if isinstance(raw, (bytes, bytearray, memoryview)):
        data = bytes(raw)
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError:
            text = data.decode("utf-8", errors="replace")
    else:
        text = str(raw)
        if any("\ud800" <= ch <= "\udfff" for ch in text):
            # 已存在的孤立代理项（如上层 latin1 误解码结果）不能进入 JSON，按 UTF-8 往返修复
            text = text.encode("utf-8", errors="surrogatepass").decode("utf-8", errors="replace") \
                if False else "".join(
                    "\ufffd" if "\ud800" <= ch <= "\udfff" else ch for ch in text)
    # NUL 会让部分 JSON/HTTP 客户端截断文本，仅替换展示副本
    return text.replace("\x00", "\ufffd") if "\x00" in text else text


